import * as React from 'react';

export function Track({ src, onReady }) {
  const handleLoaded = React.useCallback(function handleLoaded(event) {
    onReady(event.currentTarget.duration);
  }, [onReady]);

  return (
    <div>
      <audio src={src} onLoadedData={handleLoaded} />
      <video src={src} onLoadedData={handleLoaded} />
    </div>
  );
}

import React, { useCallback as useStableCallback, useState } from 'react';

export default function SearchBox({ onSearch }: { onSearch: (q: string) => void }) {
  const [query, setQuery] = useState('');
  const submit = useStableCallback(() => {
    onSearch(query.trim());
  }, [onSearch, query]);

  return (
    <form
      onSubmit={(event) => {
        event.preventDefault();
        submit();
      }}
    >
      <input value={query} onChange={(event) => setQuery(event.target.value)} />
    </form>
  );
}

import { useCallback, useEffect, useRef } from 'react';

export function useAutosave(save: (value: string) => void, value: string) {
  const timer = useRef<number>();
  const flush = useCallback(() => {
    save(value);
  }, [save, value]);

  useEffect(() => {
    timer.current = window.setTimeout(() => flush(), 500);
    return () => window.clearTimeout(timer.current);
  });

  if (value.length > 1000) {
    flush();
  }
}

import * as R from 'react';

export function Copy({ text }: { text: string }) {
  const copy = R.useCallback(() => {
    void navigator.clipboard.writeText(text);
  }, [text]);
  return <button type="button" onClick={copy}>Copy</button>;
}

import React from 'react';

const { useCallback, useState } = React;

export function Toggle() {
  const [on, setOn] = useState(false);
  const flip = useCallback(() => setOn((value) => !value), []);
  return <input type="checkbox" checked={on} onChange={flip} />;
}

import { useCallback, type ChangeEventHandler } from 'react';

export function NameField({ onName }: { onName: (name: string) => void }) {
  const handleChange = useCallback((event) => {
    onName(event.currentTarget.value);
  }, [onName]) as ChangeEventHandler<HTMLInputElement>;
  const handleBlur = useCallback(() => onName(''), [onName]) satisfies () => void;
  return <input onChange={handleChange} onBlur={handleBlur} />;
}

