import { useCallback } from 'react';

export function GoLink({ to }: { to: string }) {
  const go = useCallback(() => window.location.assign(to), [to]);
  return <a onClick={(go)}>go</a>;
}

import { useCallback } from 'react';

export function Row({ id, editable, onEdit }: { id: string; editable: boolean; onEdit: (id: string) => void }) {
  const edit = useCallback(() => onEdit(id), [id, onEdit]);
  return <li onDoubleClick={editable && edit}>{id}</li>;
}

import { useCallback } from 'react';

export function Notify({ message }: { message: string }) {
  const notify = useCallback(() => window.alert(message), [message]);
  return <button type="button" onClick={() => notify!()}>Notify</button>;
}

import { useCallback, useState } from 'react';

export function Marker() {
  const [hovered, setHovered] = useState(false);
  const over = useCallback(() => setHovered(true), []);
  return <mesh onPointerOver={over} scale={hovered ? 1.2 : 1} />;
}

import { useCallback } from 'react';
import { FilterRow } from './FilterRow';

export const FilterList = ({ filters, onChange }: { filters: string[]; onChange: (f: string[]) => void }) => {
  const makeRemove = useCallback(
    (index: number) => () => onChange(filters.filter((_, i) => i !== index)),
    [filters, onChange],
  );

  return (
    <ul>
      {filters.map((filter, index) => (
        <FilterRow key={filter} label={filter} onDelete={makeRemove(index)} />
      ))}
    </ul>
  );
};

import { memo, useCallback } from 'react';

export const Toolbar = memo(function Toolbar({ onBold }: { onBold?: () => void }) {
  const bold = useCallback(() => {
    onBold?.();
  }, [onBold]);

  return (
    <div role="toolbar" onKeyDown={(e) => e.key === 'b' && e.metaKey && bold?.()}>
      <button type="button" onClick={bold}>B</button>
    </div>
  );
});

