import { useCallback } from 'react';
import { motion } from 'framer-motion';

export function Fade({ onDone }: { onDone: () => void }) {
  const handleEnd = useCallback(() => onDone(), [onDone]);
  return <motion.div animate={{ opacity: 0 }} onAnimationComplete={handleEnd} />;
}

import { useCallback, useEffect, useState } from 'react';

export function useResize() {
  const [width, setWidth] = useState(0);
  const measure = useCallback(() => setWidth(window.innerWidth), []);

  useEffect(() => {
    measure();
  }, [measure]);

  return width;
}

import { useCallback, useState } from 'react';

export function useToggle(initial = false) {
  const [on, setOn] = useState(initial);
  const toggle = useCallback(() => setOn((value) => !value), []);
  return [on, toggle] as const;
}

import { useCallback } from 'react';

export function AutoFocus() {
  const focusRef = useCallback((node: HTMLInputElement | null) => {
    node?.focus();
  }, []);
  return <input ref={focusRef} onFocus={() => undefined} />;
}

import { useCallback, useEffect } from 'react';

export function useEscape(onEscape: () => void) {
  const handleKey = useCallback((event: KeyboardEvent) => {
    if (event.key === 'Escape') onEscape();
  }, [onEscape]);

  useEffect(() => {
    document.addEventListener('keydown', handleKey);
    return () => document.removeEventListener('keydown', handleKey);
  }, [handleKey]);
}

import { useCallback } from 'react';
import debounce from 'lodash/debounce';

export function LiveSearch({ onSearch }: { onSearch: (q: string) => void }) {
  const search = useCallback(debounce((q: string) => onSearch(q), 300), []);
  return <input onChange={(event) => search(event.target.value)} />;
}

import { useCallback } from 'react';

export function Clickable({ onPress }: { onPress: () => void }) {
  const handlePress = useCallback(() => onPress(), [onPress]);
  const handlers = { onClick: handlePress };
  return <div role="button" {...handlers} />;
}

import { createContext, useCallback, useState, type ReactNode } from 'react';

export const CountContext = createContext({ count: 0, increment: () => {} });

export function CountProvider({ children }: { children: ReactNode }) {
  const [count, setCount] = useState(0);
  const increment = useCallback(() => setCount((c) => c + 1), []);
  return <CountContext.Provider value={{ count, increment }}>{children}</CountContext.Provider>;
}

